# owner: platform
import unittest

from hourglass.parsing import parse_span
from hourglass.gaps import find_gaps

OPEN = parse_span("09:00-17:00")


def _gaps(*texts):
    spans = [parse_span(text) for text in texts]
    return find_gaps(spans, OPEN)


class FindGapsTests(unittest.TestCase):
    def test_gap_in_the_middle(self):
        found = _gaps("09:00-12:00", "13:00-17:00")
        self.assertEqual(
            found, ["gap 12:00-13:00 (60 min)"]
        )

    def test_gaps_at_both_ends(self):
        found = _gaps("10:00-16:00")
        self.assertEqual(found, [
            "gap 09:00-10:00 (60 min)",
            "gap 16:00-17:00 (60 min)"
        ])

    def test_nobody_working_is_one_big_gap(self):
        found = _gaps()
        self.assertEqual(
            found, ["gap 09:00-17:00 (480 min)"]
        )

    def test_overlap_and_touching_leave_no_gap(self):
        found = _gaps(
            "09:00-13:00", "12:00-15:00", "15:00-17:00"
        )
        self.assertEqual(found, [])

    def test_unordered_input(self):
        found = _gaps("14:00-17:00", "09:00-11:00")
        self.assertEqual(
            found, ["gap 11:00-14:00 (180 min)"]
        )

    def test_starts_before_opening_raises(self):
        with self.assertRaises(ValueError):
            _gaps("08:00-12:00")

    def test_ends_after_opening_raises(self):
        with self.assertRaises(ValueError):
            _gaps("16:00-18:00")
